export const BODY: string = "\n<p>کنٹراسٹ درست کرنا صرف چند منٹ کا کام ہے۔ آپ تصویر اپ لوڈ کرتے ہیں، سلائیڈر کھینچتے ہیں، روشن اور اندھیرے حصے دیکھتے ہیں اور زیادہ جاندار نسخہ ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنمائی پورا عمل قدم بہ قدم سمجھاتی ہے۔ اس میں سلائیڈر، فوری پری سیٹس، موازنے کے طریقے اور ایکسپورٹ کی ترتیبات شامل ہیں، تاکہ نتیجہ صاف رہے۔</p>\n<p>آخر تک آپ پھیکی لینڈ سکیپ کو ٹھیک کر سکیں گے، سخت پورٹریٹ کو نرم کر سکیں گے یا پھیکی اسکرین شاٹ کو تیز کر سکیں گے، کسی بھی ڈیوائس پر۔ اصل تصویر اس وقت تک رکھیں، جب تک نتیجہ جانچ نہ لیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: تصویر کی تشخیص کریں</h2>\n<p>ٹول کھولنے سے پہلے تصویر کو غور سے دیکھیں۔ کیا وہ پھیکی اور بھوری ہے، گہرے سائے والی سخت ہے، یا رنگوں کی حد درست ہے؟ اس جواب سے معلوم ہوتا ہے کہ سلائیڈر کس سمت جانا چاہیے۔</p>\n<p>پھیکی تصویر کو دس سے بیس فیصد کا مثبت اضافہ چاہیے۔ سخت تصویر کو انتہاؤں کو نرم کرنے کے لیے دس سے بیس فیصد کی منفی حرکت چاہیے۔</p>\n<p>یہ بھی دیکھیں کہ تصویر بہت اندھیری یا بہت روشن تو نہیں۔ اندھیری اور پھیکی تصویر کو پہلے چمک چاہیے، کیونکہ صرف کنٹراسٹ اس کی سطح ٹھیک نہیں کر سکتا۔</p>\n<p>اپنے براؤزر میں <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> کھولیں۔ سب کچھ مقامی طور پر چلتا ہے، اس لیے آپ کی تصویر کبھی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<h2 id=\"step-by-step\">پانچ مراحل میں کنٹراسٹ درست کریں</h2>\n<p>تصویر، اسکرین شاٹ یا اسکین شدہ دستاویز کے لیے طریقہ ایک ہی ہے۔ اپ لوڈ کریں، درست کریں، موازنہ کریں، ایکسپورٹ کریں اور ڈاؤن لوڈ کی تصدیق کریں۔</p>\n<p>سلائیڈر کے ساتھ وقت لیں۔ چھوٹی حرکت بھی بڑا فرق ڈالتی ہے، اور پری ویو بالکل بتا دیتا ہے کہ تصویر کب درست لگتی ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھولیں۔ تصدیق کریں کہ تصویر جاندار لگے اور روشن یا اندھیرے حصوں میں تفصیل ضائع نہ ہوئی ہو۔</p>\n<h2 id=\"using-the-slider\">کنٹراسٹ والا سلائیڈر کیسے استعمال کریں</h2>\n<p>سلائیڈر منفی سے مثبت اقدار تک چلتا ہے، جہاں صفر کا مطلب کوئی تبدیلی نہیں۔ دائیں کھینچنے سے کنٹراسٹ بڑھتا ہے اور بائیں کھینچنے سے کم ہوتا ہے۔</p>\n<p>آہستہ کھینچیں اور پری ویو دیکھتے رہیں۔ براہ راست اپ ڈیٹ بالکل دکھاتا ہے کہ تصویر کیسے بدلتی ہے، اس لیے اسی مقام پر رک جائیں جہاں تصویر درست لگے۔</p>\n<p>چھوٹی تبدیلیاں بڑی سے بہتر ہوتی ہیں۔ دس سے بیس فیصد کی تبدیلی اکثر کافی ہوتی ہے، اور بڑی تبدیلی روشن حصے کاٹ دیتی ہے اور سائے کچل دیتی ہے۔</p>\n<p>اپ لوڈ کے فوراً بعد ٹول آپ کی تصویر کو جمع بیس فیصد پر دکھاتا ہے۔ یہ ابتدائی نقطہ فوراً بتاتا ہے کہ مناسب کنٹراسٹ کیسی لگتی ہے۔</p>\n<h2 id=\"using-quick-presets\">فوری پری سیٹس کیسے استعمال کریں</h2>\n<p>ٹول میں فوری پری سیٹس ہیں جو عام کنٹراسٹ کی اقدار ایک کلک میں لگا دیتے ہیں۔ یہ سلائیڈر کھینچے بغیر مختلف سطحیں جانچنے کا تیز طریقہ ہیں۔</p>\n<p>کسی پری سیٹ پر کلک کریں اور پری ویو دیکھیں۔ اگر نتیجہ قریب ہو مگر بالکل درست نہ ہو، تو وہیں سے سلائیڈر سے باریک درستی کر لیں۔</p>\n<p>پری سیٹس سے اختیارات کا موازنہ جلدی کریں۔ جمع دس فیصد والا پری سیٹ، جمع تیس فیصد والے کے ساتھ رکھ کر دیکھیں کہ تصویر کتنا کنٹراسٹ برداشت کر سکتی ہے۔</p>\n<p>ملتی جلتی تصویروں کے بیچ کے لیے ایک ہی پری سیٹ نتیجہ مستقل رکھتا ہے۔ دھندلی لینڈ سکیپس کی تصاویر اگر ایک ہی مقدار سے تیز کی جائیں تو وہ ایک سیریز لگتی ہیں۔</p>\n<h2 id=\"using-compare-modes\">موازنے کے طریقے کیسے استعمال کریں</h2>\n<p>موازنے کے طریقے اصل اور تبدیل شدہ نسخہ ساتھ دکھاتے ہیں۔ بعد والی نظر کنٹراسٹ بڑھی ہوئی تصویر دکھاتی ہے اور پہلے والی نظر اصل تصویر دکھاتی ہے۔</p>\n<p>کنٹراسٹ کے کام کے لیے اسپلٹ موازنہ سب سے مفید ہے۔ یہ دونوں نسخے ساتھ دکھاتا ہے، اس لیے آپ بالکل دیکھ سکتے ہیں کہ کون سے سائے گہرے ہوئے اور کون سے روشن حصے چمکے۔</p>\n<p>فل اسکرین موازنہ سب سے بڑا نظارہ دیتا ہے۔ کنٹراسٹ کی تبدیلی کو پرکھنے کا یہ بہترین طریقہ ہے، کیونکہ مکمل سائز کی تصویر وہ کلپنگ دکھاتی ہے جو چھوٹا پری ویو چھپا دیتا ہے۔</p>\n<p>ہر ڈاؤن لوڈ سے پہلے موازنے والی نظر ضرور دیکھیں۔ ایک تیز نظر ان کٹے ہوئے روشن حصوں اور کچلے ہوئے سائے کو پکڑ لیتی ہے جو چھوٹے پری ویو میں چھپ جائیں۔</p>\n<h2 id=\"boosting-a-flat-photo\">پھیکی تصویر میں جانداری لانا</h2>\n<p>پھیکی تصویر اپ لوڈ کریں اور سلائیڈر کو جمع پندرہ فیصد تک لے جائیں۔ پری ویو دیکھیں: سائے گہرے ہونے چاہئیں، روشن حصے چمکنے چاہئیں اور تصویر میں جان آ جانی چاہیے۔</p>\n<p>اگر تصویر اب بھی پھیکی ہو تو سلائیڈر کو پانچ فیصد کے چھوٹے قدموں میں بڑھائیں۔ ہر قدم تھوڑا سا زور بڑھاتا ہے، اور پری ویو بتاتا ہے کہ کب رکنا ہے۔</p>\n<p>آگے بڑھتے ہوئے روشن حصوں پر نظر رکھیں۔ بادل، سفید قمیضیں اور روشن جلد سب سے پہلے کٹتی ہیں اور بغیر تفصیل کے سفید دھبے بن جاتی ہیں۔</p>\n<p>اگر بڑھانے کے بعد تصویر سخت لگے تو سلائیڈر پانچ فیصد کم کریں۔ چھوٹی کمی اکثر تفصیل واپس لے آتی ہے، بغیر تصویر کو دوبارہ پھیکا کیے۔</p>\n<h2 id=\"softening-a-harsh-photo\">سخت تصویر کو نرم کرنا</h2>\n<p>دوپہر کی تیز دھوپ میں لی گئی تصویر کے لیے سلائیڈر کو بائیں کھینچیں۔ منفی دس یا منفی بیس فیصد جیسی منفی اقدار چہرے پر مضبوط سائے نرم کر دیتی ہیں۔</p>\n<p>نرم کرتے وقت چہرہ دیکھتے رہیں۔ سائے آہستہ آہستہ نرم ہونے چاہئیں، جبکہ چہرے کی مجموعی شکل واضح اور متعین رہے۔</p>\n<p>منفی کنٹراسٹ خواب جیسی نرم لینڈ سکیپس کے لیے بھی موزوں ہے۔ کم کنٹراسٹ والا دھند بھرا صبح کا منظر پرسکون اور خاموش لگتا ہے، جو تصویر کے مزاج سے ملتا ہے۔</p>\n<p>حد سے زیادہ نہ کریں۔ بہت کم کنٹراسٹ والی تصویر بھوری اور بے جان لگتی ہے، جیسے صاف دن میں بھی دھند سے لی گئی ہو۔</p>\n<h2 id=\"fixing-a-screenshot\">پھیکی اسکرین شاٹ کو ٹھیک کرنا</h2>\n<p>محفوظ کرنے کا مرحلہ چھوڑنے کے لیے اسکرین شاٹ کو کنٹرول اور وی دبا کر براہ راست چپکائیں۔ تصویر فوراً ایڈیٹر میں آ جاتی ہے اور درست کرنے کے لیے تیار ہوتی ہے۔</p>\n<p>کنٹراسٹ اتنا بڑھائیں کہ تحریر گہری ہو اور پس منظر سفید ہو۔ صاف سفید پس منظر پر مضبوط سیاہ تحریر والا دستاویز پڑھنے اور چھاپنے میں آسان ہوتا ہے۔</p>\n<p>پس منظر میں شور سے ہوشیار رہیں۔ بہت زیادہ کنٹراسٹ والا اسکین دھبے اور خرابیاں دکھا سکتا ہے، خاص طور پر اگر جے پی جی پہلے ہی کمپریس ہو چکا ہو۔</p>\n<p>اسکرین شاٹس کو پی این جی میں ایکسپورٹ کریں۔ نقصان سے پاک فارمیٹ چھوٹی تحریر کو تیز رکھتا ہے، جو اس وقت اہم ہے جب اسکرین شاٹ کوئی سیٹنگ یا غلطی کا پیغام دکھائے۔</p>\n<h2 id=\"checking-shadows-highlights\">سائے اور روشن حصے جانچنا</h2>\n<p>ہر کنٹراسٹ کی تبدیلی کے بعد تصویر کے سب سے اندھیرے اور سب سے روشن حصے الگ الگ دیکھیں۔ بڑھاوے سے سائے پہلے کچلتے ہیں اور روشن حصے پہلے کٹتے ہیں۔</p>\n<p>سائے والے حصے میں زوم کریں اور تصدیق کریں کہ اب بھی تفصیل نظر آتی ہے۔ کوٹ، درخت یا اندھیرا کونا ساخت دکھانا چاہیے، نہ کہ مکمل سیاہ دھبا۔</p>\n<p>روشن حصے میں زوم کریں اور تصدیق کریں کہ اب بھی تفصیل نظر آتی ہے۔ بادل، سفید قمیض یا روشن پیشانی شکل دکھانی چاہیے، نہ کہ سفید خالی جگہ۔</p>\n<p>اگر کسی انتہا میں تفصیل ضائع ہو گئی ہو تو سلائیڈر پانچ فیصد کم کریں اور دوبارہ دیکھیں۔ چھوٹی کمی عام طور پر زور کھوئے بغیر تفصیل واپس لے آتی ہے۔</p>\n<h2 id=\"previewing\">ڈاؤن لوڈ سے پہلے پری ویو</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پری ویو دیکھیں۔ جانچیں کہ تصویر جاندار لگے، کوئی روشن حصہ سفید نہ ہو گیا ہو اور کوئی اندھیرا حصہ سیاہ نہ ہو گیا ہو۔</p>\n<p>تبدیلی جانچنے کے لیے اسپلٹ موازنہ استعمال کریں۔ یہ اصل اور تبدیل شدہ نسخہ ساتھ دکھاتا ہے، اس لیے آپ بالکل دیکھ سکتے ہیں کہ کنٹراسٹ نے کیا کیا۔</p>\n<p>روشن اور اندھیرے حصوں کو مکمل سائز میں زوم کر کے دیکھیں۔ آسمان یا سایہ چھوٹے پری ویو میں ٹھیک لگے مگر بڑے سائز میں کٹا یا کچلا ہوا نکلے۔</p>\n<p>اگر نتیجہ سخت لگے تو سلائیڈر پانچ فیصد کم کریں اور دوبارہ دیکھیں۔ چھوٹی کمی اکثر تفصیل واپس لے آتی ہے، بغیر تصویر کو دوبارہ پھیکا کیے۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ کا انتخاب</h2>\n<p>بانٹنے والی تصویروں کے لیے جے پی جی چنیں۔ یہ فائل کا حجم چھوٹا رکھتا ہے، ہر جگہ کام کرتا ہے اور اعلیٰ معیار کی سیٹنگ کنٹراسٹ والی تصویر کو صاف رکھتی ہے۔</p>\n<p>تحریر والی اسکرین شاٹس اور گرافکس کے لیے پی این جی چنیں۔ پی این جی نقصان سے پاک ہے، اس لیے حروف کے کنارے تیز رہتے ہیں اور ضرورت ہو تو شفافیت بھی بچ جاتی ہے۔</p>\n<p>چھوٹی فائل اور اچھا معیار چاہتے ہوں تو ویب پی چنیں۔ یہ ویب تصاویر کے لیے اچھا کام کرتا ہے، اگرچہ چند پرانے نظام اب بھی اسے رد کر دیتے ہیں۔</p>\n<p>یاد رکھیں کہ پی این جی کے لیے معیار والا سلائیڈر چھپ جاتا ہے، کیونکہ پی این جی نقصان سے پاک ہے اور اس کی کوئی معیار کی سیٹنگ نہیں ہوتی۔ یہ عام رویہ ہے، ٹول کا مسئلہ نہیں۔</p>\n<h2 id=\"adjusting-on-mobile\">فون یا ٹیبلٹ پر کنٹراسٹ درست کرنا</h2>\n<p>یہ ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ پھیکی تصویر اسی فون پر ٹھیک کر سکتے ہیں جس سے وہ لی گئی ہو۔ گیلری سے اپ لوڈ کریں، سلائیڈر انگلی سے کھینچیں اور ڈاؤن لوڈ کریں۔</p>\n<p>انگلی سے سلائیڈر کھینچنا ماؤس سے کم درست ہوتا ہے۔ درست اقدار کے لیے فوری پری سیٹس استعمال کریں، پھر چھوٹی حرکتوں سے باریک درستی کریں۔</p>\n<p>ڈاؤن لوڈ سے پہلے پری ویو مکمل سائز میں دیکھیں۔ چھوٹی فون اسکرین پر ٹھیک لگنے والی تبدیلی کمپیوٹر پر بہت زیادہ نکل سکتی ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائلیں آپ کے معمول کے ڈاؤن لوڈ فولڈر میں جاتی ہیں۔ وہاں سے تبدیل شدہ تصویر کو براہ راست چیٹ ایپ، ای میل یا سوشل پوسٹ پر بانٹ سکتے ہیں۔</p>\n<h2 id=\"troubleshooting\">عام کنٹراسٹ کے مسائل کا حل</h2>\n<p>اگر تصویر سخت لگے تو سلائیڈر بہت اونچا ہے۔ اسے چھوٹے قدموں میں کم کریں، جب تک جلد، آسمان اور سائے والے حصوں میں ساخت واپس نہ آ جائے۔</p>\n<p>اگر بڑھانے کے بعد بھی تصویر پھیکی رہے تو اصل تصویر بہت دھندلی ہو سکتی ہے۔ گھنی دھند سے لی گئی تصویر میں وہ تفصیل نہیں آ سکتی جو کبھی قید ہی نہیں ہوئی۔</p>\n<p>اگر روشن حصے کٹے ہوئے ہوں تو سلائیڈر کم کریں اور روشن حصے مکمل سائز میں دیکھیں۔ چھوٹی کمی عام طور پر بادل یا جلد کی تفصیل واپس لے آتی ہے۔</p>\n<p>اگر پری ویو ڈاؤن لوڈ سے مختلف لگے تو ایکسپورٹ فارمیٹ اور معیار دیکھیں۔ جے پی جی کی کم معیار کی سیٹنگ پوری تصویر کو نرم کر دیتی ہے، کنٹراسٹ سمیت۔</p>\n<h2 id=\"contrast-plus-brightness\">کنٹراسٹ اور چمک: عام جوڑی</h2>\n<p>جو تصویر اندھیری اور پھیکی دونوں ہو، اسے چمک اور کنٹراسٹ دونوں چاہئیں۔ پہلے روشن کریں تاکہ مجموعی سطح اوپر آئے، پھر کنٹراسٹ شامل کریں تاکہ گہرائی واپس آئے۔</p>\n<p>کنٹراسٹ شامل کرنے سے پہلے اگر تصویر اندھیری ہو تو <a href=\"/ur/tasveer-ki-brightness-badlein/\">Image Brightness Editor</a> استعمال کریں۔ اندھیری تصویر پر کنٹراسٹ کا اضافہ صرف سائے گہرے کرتا ہے۔</p>\n<p>مراحل اسی ترتیب میں کریں: پہلے چمک، پھر کنٹراسٹ۔ الٹی ترتیب سے کنٹراسٹ کا اندازہ مشکل ہو جاتا ہے، کیونکہ تصویر اب بھی اندھیری ہوتی ہے۔</p>\n<p>ہر مرحلے کے بعد موازنے والی نظر دیکھیں۔ اسپلٹ نظر بالکل دکھاتی ہے کہ ہر تبدیلی نے کیا کیا، اس لیے جب تصویر درست لگے تو رک جائیں۔</p>\n<h2 id=\"saving-settings\">اگلی بار کے لیے سیٹنگز محفوظ کرنا</h2>\n<p>ملتی جلتی تصویروں کے لیے کام کرنے والی کنٹراسٹ کی قدر لکھ لیں۔ دھندلی لینڈ سکیپس کے لیے جمع بیس فیصد جیسی مختصر نوٹ اگلی بار اندازہ لگانے سے بچاتی ہے۔</p>\n<p>ایک ہی روشنی میں لی گئی تصویروں کے بیچ کے لیے ایک ہی قدر استعمال کریں۔ پورے سیٹ میں مستقل کنٹراسٹ پیشہ ورانہ لگتا ہے، جبکہ ملی جلی قدریں بے ترتیب لگتی ہیں۔</p>\n<p>اصل فائلیں رکھیں۔ ایک تصویر کے لیے کام کرنے والی کنٹراسٹ کی قدر دوسری کے لیے موزوں نہ ہو، اور اصل فائل سے آپ بغیر اضافی نقصان کے دوسری سطح آزما سکتے ہیں۔</p>\n<p>اپنی نوٹس کبھی کبھار دیکھتے رہیں۔ جیسے جیسے آپ کا کیمرہ اور روشنی بہتر ہوتی ہے، درکار کنٹراسٹ کی قدریں بھی بدلتی ہیں اور پرانی نوٹس گمراہ کر سکتی ہیں۔</p>\n<h2 id=\"quick-tips\">بہتر کنٹراسٹ کے لیے فوری نکات</h2>\n<p>چھوٹے قدموں میں درست کریں۔ ایک وقت میں پانچ فیصد کی تبدیلی آپ کو قابو دیتی ہے، جبکہ بڑی چھلانگ درست قدر سے آگے نکل سکتی ہے۔</p>\n<p>صرف درمیانی رنگ نہیں، انتہائیں بھی دیکھیں۔ تصویر اس وقت زیادہ کنٹراسٹ والی ہوتی ہے جب روشن حصے کٹ جائیں یا سائے کچل جائیں، چاہے درمیانی رنگ اچھے لگیں۔</p>\n<p>ہر بار موازنے والی نظر استعمال کریں۔ اصل کے ساتھ تبدیل شدہ نسخہ کی ایک تیز نظر ان غلطیوں کو پکڑ لیتی ہے جو چھوٹا پری ویو چھپاتا ہے۔</p>\n<p>اصل تصویر بغیر تبدیلی کے محفوظ کریں۔ ایک بار کنٹراسٹ کی تبدیلی ایکسپورٹ میں شامل ہو جائے تو اس فائل سے واپس نہیں ہو سکتی۔</p>\n<h2 id=\"contrast-for-product-photo\">پروڈکٹ فوٹو میں کنٹراسٹ شامل کرنا</h2>\n<p>پروڈکٹ فوٹو کو واضح کنٹراسٹ چاہیے تاکہ چیز پس منظر سے الگ نظر آئے۔ پھیکی پروڈکٹ تصویر بے جان لگتی ہے، جبکہ جاندار تصویر آنکھ کو چیز کی طرف کھینچتی ہے۔</p>\n<p>زیادہ تر پروڈکٹس کے لیے دس سے بیس فیصد کا مناسب اضافہ استعمال کریں۔ چیز ٹھوس اور متعین نظر آنی چاہیے، پس منظر کے خلاف کنارے واضح ہوں۔</p>\n<p>کنٹراسٹ بڑھاتے وقت پروڈکٹ کے رنگ دیکھتے رہیں۔ بہت زیادہ اضافہ رنگوں کو سخت بنا سکتا ہے، اس لیے صرف پس منظر نہیں، خود چیز کو دیکھیں۔</p>\n<p>پورے کیٹلاگ میں کنٹراسٹ مستقل رکھیں۔ ملتی جلتی کنٹراسٹ سطحوں والی دکان صاف اور قابل اعتماد لگتی ہے، جبکہ ملی جلی سطحیں لاپرواہ لگتی ہیں۔</p>\n<p>موازنے کے لیے <a href=\"/ur/blog/brightness-vs-exposure-vs-contrast/\">Brightness vs Exposure vs Contrast: Editing Basics</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-contrast-editor-rehnumai/\">Image Contrast Editor: Complete Guide</a> دیکھیں، اور اندھیری تصویر کو ٹھیک کرنے کے لیے چمک والا ایڈیٹر استعمال کریں۔</p>\n<ul>\n<li>اپنی تصویر ڈراپ زون میں کھینچ کر، ڈیوائس سے چن کر، یا کنٹرول اور وی دبا کر اسکرین شاٹ چپکا کر اپ لوڈ کریں۔</li>\n<li>کنٹراسٹ بڑھانے کے لیے کنٹراسٹ لیول سلائیڈر کو دائیں اور کم کرنے کے لیے بائیں کھینچیں، براہ راست پری ویو دیکھتے ہوئے۔</li>\n<li>ایک کلک کی آزمائش کے لیے فوری پری سیٹ آزمائیں، پھر اگر نتیجہ قریب ہو مگر بالکل درست نہ ہو تو سلائیڈر سے باریک درستی کریں۔</li>\n<li>ڈاؤن لوڈ سے پہلے موازنے کے طریقوں سے روشن اور اندھیرے حصے اصل سے دیکھیں۔</li>\n<li>ایکسپورٹ فارمیٹ اور معیار چنیں، پھر درست شدہ تصویر محفوظ کرنے کے لیے ڈاؤن لوڈ پر کلک کریں۔</li>\n</ul>";

export const FAQS: BlogArticleFaq[] = [{"question":"میں اپنے فون پر تصویر میں کنٹراسٹ کیسے شامل کروں؟","answer":"اپنے فون کے براؤزر میں Image Contrast Editor کھولیں، گیلری سے تصویر اپ لوڈ کریں اور انگلی سے سلائیڈر کو دائیں کھینچیں۔ درست قدر کے لیے فوری پری سیٹ استعمال کریں، موازنے والی نظر سے نتیجہ دیکھیں اور پھر ڈاؤن لوڈ کریں۔"},{"question":"دھندلی لینڈ سکیپ کے لیے کون سی کنٹراسٹ کی قدر استعمال کروں؟","answer":"جمع پندرہ سے بیس فیصد سے شروع کریں اور آسمان دیکھیں۔ دھند رنگوں کی حد چپٹا کر دیتی ہے، اس لیے مناسب اضافہ گہرائی واپس لاتا ہے۔ بادل سفید خالی جگہ بننے سے پہلے رک جائیں، اور روشن حصے کٹیں تو سلائیڈر کم کریں۔"},{"question":"کیا میں کنٹراسٹ کم کر کے سخت پورٹریٹ کو نرم کر سکتا ہوں؟","answer":"جی ہاں۔ سلائیڈر کو بائیں کھینچیں، منفی دس یا منفی بیس فیصد جیسی منفی اقدار تک۔ منفی کنٹراسٹ چہرے پر مضبوط سائے نرم کرتا ہے، بغیر اس کی شکل کھوئے۔ جلد دیکھتے رہیں تاکہ وہ قدرتی رہے۔"},{"question":"کنٹراسٹ شامل کرنے کے بعد میری تصویر کے روشن حصے سفید کیوں ہو جاتے ہیں؟","answer":"کنٹراسٹ بہت زیادہ بڑھا دیا گیا، جس سے روشن ترین حصے خالص سفید میں کٹ گئے۔ سلائیڈر کو چھوٹے قدموں میں کم کریں، جب تک بادل، جلد اور سفید سطحیں دوبارہ تفصیل نہ دکھائیں۔ دس سے بیس فیصد کا اضافہ عام طور پر کافی ہوتا ہے۔"},{"question":"کیا کنٹراسٹ چمک سے پہلے درست کروں یا بعد میں؟","answer":"پہلے چمک، پھر کنٹراسٹ۔ چمک مجموعی سطح طے کرتی ہے اور کنٹراسٹ اس سطح کے ارد گرد پھیلاؤ کو بہتر بناتا ہے۔ اندھیری تصویر کو پہلے روشن کرنا چاہیے، کیونکہ صرف کنٹراسٹ اس کی سطح ٹھیک نہیں کر سکتا۔"},{"question":"کیا میں ڈاؤن لوڈ کے بعد کنٹراسٹ کی تبدیلی واپس کر سکتا ہوں؟","answer":"ڈاؤن لوڈ شدہ فائل سے نہیں، کیونکہ تبدیلی ایکسپورٹ میں شامل ہو جاتی ہے۔ اصل تصویر رکھیں تاکہ آپ دوسری کنٹراسٹ کی سطح آزما سکیں۔ ٹول میں، ڈاؤن لوڈ سے پہلے صفر پر واپس جانے کے لیے ری سیٹ کا آپشن استعمال کریں۔"}];
